import React, { useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { ArrowUpRight, ArrowRight, ArrowLeft, Check, CheckCheck, ShieldCheck, LockKeyhole, KeyRound, Layers, Search, CircleHelp, ChevronDown, ChevronRight, Copy, CheckCircle2, CircleAlert, Clock3, LoaderCircle, Download, Upload, X, Settings2, LogOut, LayoutDashboard, CreditCard, ExternalLink, RefreshCw, Menu, Terminal, Pause, FileJson, Eye, EyeOff, Leaf } from 'lucide-react';
import { api, submissionKey, downloadJson, parseSession, parseCardList, parseBatchSessions } from './api';
import { appPath, pagePath } from '../app-path.mjs';
import './styles.css';
import './compact.css';
import './portal.css';

const DEFAULTS = { siteName: 'LIMEN 礼门', announcement: '', configured: false, verificationConfigured: false, maintenance: false, allowBatch: true, supportText: '如需帮助，请联系向您提供卡密的商家。' };
const STATUS = { pending: ['排队中', 'pending'], processing: ['处理中', 'pending'], pending_verification: ['待核验', 'attention'], success: ['兑换成功', 'success'], failed: ['兑换失败', 'failed'] };
const mask = v => !v ? '—' : v.length < 9 ? '••••' : `${v.slice(0, 4)} ··· ${v.slice(-4)}`;
function Spinner() { return <LoaderCircle size={17} className="spin" />; }
function Alert({ children, type = 'error' }) { return children ? <div className={`alert ${type}`} role={type === 'error' ? 'alert' : 'status'}><CircleAlert size={17}/><div>{children}</div></div> : null; }
function Brand({ name }) { return <a className="brand" href={appPath('/')} aria-label="礼门首页"><span className="brand-symbol"><span/><i/></span><span>{name && name !== 'LIMEN 礼门' ? name : '礼门'}<span className="brand-en">LIMEN</span></span></a>; }
function Header({ path, name }) {
  const [open, setOpen] = useState(false);
  return <header className="header"><div className="header-inner"><Brand name={name}/><nav className={open ? 'nav open' : 'nav'} aria-label="主导航"><a className={path === 'recharge' ? 'active' : ''} href={appPath('/')}>兑换中心</a><a className={path === 'orders' ? 'active' : ''} href={appPath('/orders')}>订单查询</a><a className={path === 'help' ? 'active' : ''} href={appPath('/help')}>使用帮助<ArrowUpRight size={13}/></a></nav><div className="header-right"><span className="header-tag"><span className="live-dot"/>安心兑换，轻松抵达</span><button className="mobile-menu icon-button" aria-label="展开导航" onClick={() => setOpen(!open)}><Menu size={22}/></button></div></div></header>;
}
function Footer() { return <footer className="footer"><div><span className="footer-mark">LIMEN</span><span>让每一次连接，都更简单。</span></div><div><a href={appPath('/help#privacy')}>隐私与安全</a><span>© {new Date().getFullYear()} 礼门</span></div></footer>; }
function PortalHeader({ path, settings, ready }) {
  const links = [['recharge', '/', '充值提交'], ['orders', '/orders', '订单查询'], ['subscription', '/subscription', '订阅查询'], ['help', '/help', '使用帮助']];
  return <header className="portal-header"><div className="portal-title"><a href={appPath('/')} className="portal-logo" aria-label={`${settings.siteName}首页`}>礼</a><div><span className="portal-eyebrow">ACCOUNT UPGRADE SERVICE</span><h1>充值与账户升级服务</h1><p>按步骤校验卡密、填写 Session 并确认信息</p></div></div><div className="portal-navigation"><nav aria-label="兑换站功能">{links.map(([id, href, title])=><a key={id} href={appPath(href)} className={path===id?'active':''} aria-current={path===id?'page':undefined}>{title}</a>)}</nav><span className="portal-status"><span className="live-dot"/>{!ready?'连接中':settings.maintenance?'兑换维护中':settings.configured&&settings.verificationConfigured?'兑换服务已就绪':'兑换服务待配置'}</span></div></header>;
}
function ProgressSteps({ stage }) {
  return <ol className="progress-steps" aria-label="充值进度">{['CDK 验证','提交 Session','确认提交'].map((label,i)=><li key={label} className={stage>=i+1?'current':''} aria-current={stage===i+1?'step':undefined}><span>{stage>i+1?<Check size={16}/>:i+1}</span><b>{label}</b></li>)}</ol>;
}
function StepLabel({ number, title, extra }) { return <div className="step-label"><span>{number}</span><label>{title}</label>{extra && <small>{extra}</small>}</div>; }
function Guide({ settings }) {
  return <aside className="sidebar"><div className="guide-card"><span className="eyebrow">A LITTLE GUIDANCE</span><h3>兑换，只需三步<span>。</span></h3><div className="guide-steps">{[['01', '先验证卡密', '输入商家提供的卡密并验证。'], ['02', '粘贴账号 Session', '验证通过后填写完整账号信息。'], ['03', '确认并等待结果', '保留订单号，随时查询进度。']].map(([n,t,d]) => <div className="guide-step" key={n}><span>{n}</span><div><h4>{t}</h4><p>{d}</p></div></div>)}</div><a className="text-link" href={appPath('/help')}>第一次使用？查看详细指南<ArrowUpRight size={15}/></a></div><div className="privacy-card"><ShieldCheck size={24} strokeWidth={1.5}/><h4>您的信息，妥善守护</h4><p>Session 仅用于本次兑换，不在本站数据库留存。请勿将账号凭据分享给他人。</p><a href={appPath('/help#privacy')}>了解安全说明<ArrowRight size={14}/></a></div><div className="help-note"><CircleHelp size={18}/><div><b>遇到问题？</b><p>{settings.supportText}</p></div></div></aside>;
}
function Hero({ tag = 'REDEMPTION, SIMPLIFIED.', title, subtitle, compact = false }) {
  return <section className={`hero ${compact ? 'compact' : ''}`}><div><div className="eyebrow"><span/> {tag}</div><h1>{title}</h1><p>{subtitle}</p></div>{!compact && <div className="hero-art" aria-hidden="true"><div className="art-orbit"/><div className="ticket"><div className="ticket-brand"><span className="tiny-leaf">✳</span> LIMEN <ArrowUpRight size={17}/></div><div className="ticket-lines"><i/><i/></div><div className="ticket-bottom"><span>GOOD THINGS<br/>ARE ON THE WAY.</span><span className="ticket-seal"><Check size={22}/></span></div></div><span className="art-caption">A simple code. A new possibility.</span><span className="art-spark">✳</span></div>}</section>;
}
function Recharge({ settings, ready }) {
  const [mode, setMode] = useState('single'); const [cardKey, setCardKey] = useState(''); const [session, setSession] = useState(''); const [batch, setBatch] = useState(''); const [batchSessions, setBatchSessions] = useState(''); const [recoverMode, setRecoverMode] = useState(false); const [recoveryKey, setRecoveryKey] = useState('');
  const [agreed, setAgreed] = useState(false); const [busy, setBusy] = useState(false); const [verifying, setVerifying] = useState(false); const [singleVerification, setSingleVerification] = useState(null); const [batchVerifications, setBatchVerifications] = useState(null); const [verificationProgress, setVerificationProgress] = useState(''); const [error, setError] = useState(''); const [items, setItems] = useState([]); const [orders, setOrders] = useState([]); const [attempt, setAttempt] = useState('');
  const [show, setShow] = useState(false); const stop = useRef(false); const fileRef = useRef(); const sessionFileRef = useRef(); const actionLock = useRef(false); const verifyLock = useRef(false);
  let account; try { account = parseSession(session).user.email; } catch { /* Show only validated account. */ }
  const disabled = !ready || settings.maintenance || !settings.configured || !settings.verificationConfigured;
  async function importFile(e) {
    const file = e.target.files?.[0]; if (!file) return;
    if (file.size > 512000) { setError('文件不能超过 500 KB。'); return; }
    const text = await file.text(); setBatch(text); setBatchVerifications(null); setBatchSessions(''); setError(''); e.target.value = '';
  }
  async function importSessions(e) {
    const file = e.target.files?.[0]; if (!file) return;
    if (file.size > 512000) { setError('文件不能超过 500 KB。'); e.target.value = ''; return; }
    setBatchSessions(await file.text()); setError(''); e.target.value = '';
  }
  async function verifyCards() {
    if (verifyLock.current || verifying || busy) return;
    setError(''); let cards;
    try { cards = mode === 'single' ? parseCardList(cardKey) : parseCardList(batch); if (mode === 'single' && cards.length !== 1) throw new Error('单个兑换请只输入一张卡密。'); }
    catch (e) { setError(e.message); return; }
    verifyLock.current = true; setVerifying(true); setVerificationProgress('');
    if (mode === 'single') setSingleVerification(null); else setBatchVerifications(null);
    try {
      const verified = [];
      for (let i = 0; i < cards.length; i++) {
        setVerificationProgress(`正在验证 ${i + 1} / ${cards.length}`);
        try {
          if (mode === 'single' && recoverMode) {
            if (!/^[A-Za-z\d_-]{1,128}$/.test(recoveryKey.trim())) throw new Error('请输入原提交标识。');
            const result = await api('/card-keys/recover', { method: 'POST', body: { cardKey: cards[i], submissionKey: recoveryKey.trim() } });
            verified.push({ cardKey: cards[i], ...result, verificationToken: '', recoveryKey: recoveryKey.trim(), planLabel: '仅恢复原提交，请填写原来的 Session' });
          } else {
            const result = await api('/card-keys/verify', { method: 'POST', body: { cardKey: cards[i] }, headers: mode === 'batch' ? { 'X-Batch-Mode': '1' } : {} });
            verified.push({ cardKey: cards[i], ...result });
          }
        } catch (e) { throw new Error(mode === 'batch' ? `第 ${i + 1} 张卡密：${e.message}` : e.message); }
        if (i < cards.length - 1) await new Promise(resolve => setTimeout(resolve, 850));
      }
      if (mode === 'single') setSingleVerification(verified[0]); else setBatchVerifications(verified);
    } catch (e) { setError(e.message); }
    finally { verifyLock.current = false; setVerifying(false); setVerificationProgress(''); }
  }
  async function submit(e) {
    e.preventDefault(); if (actionLock.current) return; setError('');
    if (!agreed) { setError('请先阅读并确认下方兑换须知。'); return; }
    let payloads;
    try {
      if (mode === 'single' && (!singleVerification || singleVerification.cardKey !== cardKey.trim())) throw new Error('请先验证当前卡密。');
      if (mode === 'batch' && !batchVerifications) throw new Error('请先验证全部卡密。');
      payloads = mode === 'single' ? [{ orderType: 'card_key', cardKey: cardKey.trim(), token: parseSession(session) }] : parseBatchSessions(batchSessions, batchVerifications);
    } catch (e) { setError(e.message); return; }
    actionLock.current = true; setBusy(true); stop.current = false;
    const results = payloads.map((p, i) => ({ index: i+1, card: mask(p.cardKey), email: p.token.user.email, state: 'waiting' })); setItems([...results]);
    let allSucceeded = true;
    for (let i = 0; i < payloads.length; i++) {
      if (stop.current) { allSucceeded = false; break; }
      results[i].state = 'submitting'; setItems([...results]);
      try {
        const verified = mode === 'single' ? singleVerification : batchVerifications[i];
        const key = verified.recoveryKey || await submissionKey(payloads[i]); setAttempt(key); results[i].attempt = key;
        const headers = { 'Idempotency-Key': key, 'X-Card-Verification': verified.verificationToken, ...(mode === 'batch' ? { 'X-Batch-Mode': '1' } : {}) };
        let result;
        try { result = await api('/orders', { method: 'POST', body: payloads[i], headers }); }
        catch (e) {
          if (e.code !== 'CARD_VERIFICATION_REQUIRED' || verified.recoveryKey) throw e;
          const renewed = await api('/card-keys/verify', { method: 'POST', body: { cardKey: payloads[i].cardKey }, headers: mode === 'batch' ? { 'X-Batch-Mode': '1' } : {} });
          result = await api('/orders', { method: 'POST', body: payloads[i], headers: { ...headers, 'X-Card-Verification': renewed.verificationToken } });
        }
        results[i] = { ...results[i], state: 'submitted', order: result.order }; setOrders(old => [result.order, ...old.filter(x => x.order_no !== result.order.order_no)]);
      } catch (e) {
        allSucceeded = false; results[i] = { ...results[i], state: e.code === 'RESULT_UNKNOWN' ? 'unknown' : 'error', message: e.message };
        setError(e.message);
        if (e.status === 429 || ['RESULT_UNKNOWN','UPSTREAM_INVALID','NOT_CONFIGURED','MAINTENANCE','IN_FLIGHT','CARD_INVALID','VERIFICATION_UNAVAILABLE','CARD_VERIFICATION_REQUIRED'].includes(e.code)) stop.current = true;
      }
      setItems([...results]);
      if (i < payloads.length - 1 && !stop.current) await new Promise(r => setTimeout(r, 850));
    }
    if (allSucceeded) { setSession(''); setCardKey(''); setBatch(''); setBatchSessions(''); setSingleVerification(null); setBatchVerifications(null); setRecoveryKey(''); setRecoverMode(false); setAgreed(false); }
    setBusy(false); actionLock.current = false;
  }
  return <><Hero title={<>让每一次兑换，<em>都简单一点。</em></>} subtitle="一枚卡密，开启新的可能。准备好账号信息，剩下的交给我们。"/>
    <div className="notice"><span className="notice-label">服务公告</span><span>{settings.announcement || '请确认账号信息后再兑换，提交成功后请保留完整订单号。'}</span><ArrowUpRight size={15}/></div>
    <div className="workspace"><main className="main-column"><section className="redeem-card"><div className="card-heading"><div><span className="section-kicker">REDEEM YOUR CODE</span><h2>开启您的兑换</h2></div><span className={`service-badge ${disabled ? 'offline' : ''}`}><span className="live-dot"/>{!ready ? '连接中' : settings.maintenance ? '维护中' : !settings.configured || !settings.verificationConfigured ? '待配置' : '服务已就绪'}</span></div>
    <div className="tabs" role="tablist" aria-label="提交方式"><button type="button" role="tab" aria-selected={mode === 'single'} disabled={busy || verifying} className={mode === 'single' ? 'selected' : ''} onClick={() => { setMode('single'); setError(''); }}><KeyRound size={16}/>单个提交</button><button type="button" role="tab" aria-selected={mode === 'batch'} disabled={busy || verifying || !settings.allowBatch} className={mode === 'batch' ? 'selected' : ''} onClick={() => { setMode('batch'); setError(''); }}><Layers size={16}/>批量提交<span className="tab-tag">最多 50 组</span></button></div>
    <ProgressSteps stage={agreed?3:(mode==='single'?singleVerification:batchVerifications)?2:1}/>
    <form onSubmit={submit} className="redeem-form">
    {(mode==='single'?singleVerification:batchVerifications)&&<div className="verified-summary"><span><CheckCircle2 size={16}/>{mode==='single'?`${singleVerification.recoveryKey?'已找到原提交':'卡密验证通过'} · ${singleVerification.planLabel}`:`${batchVerifications.length} 张卡密全部验证通过`}</span><button type="button" className="subtle-link" disabled={busy||verifying} onClick={()=>{setSingleVerification(null);setBatchVerifications(null);setSession('');setBatchSessions('');setAgreed(false);setError('');}}>修改卡密</button></div>}
    <fieldset disabled={busy || verifying || disabled}>
    {mode === 'single' ? <><div className="form-section"><StepLabel number="01" title="验证兑换卡密" extra="CDK CODE"/><label className="sr-only" htmlFor="card-key">兑换卡密</label><div className="input-icon"><KeyRound size={18}/><input id="card-key" required autoComplete="off" spellCheck="false" maxLength={128} value={cardKey} onChange={e => { setCardKey(e.target.value); setSingleVerification(null); setSession(''); setAgreed(false); setError(''); }} placeholder="请输入商家提供的兑换卡密"/></div><p className="field-hint">卡密区分大小写，验证通过后再填写账号信息。</p><button type="button" className="subtle-link recovery-toggle" onClick={()=>{setRecoverMode(!recoverMode);setSingleVerification(null);setSession('');setAgreed(false);setError('');}}>{recoverMode?'返回正常验证':'恢复结果未确认的原提交'}</button>{recoverMode&&<><label className="input-label" htmlFor="recovery-key">原提交标识</label><input id="recovery-key" value={recoveryKey} maxLength={128} autoComplete="off" onChange={e=>{setRecoveryKey(e.target.value);setSingleVerification(null);setSession('');setAgreed(false);}} placeholder="输入之前保存的提交标识"/><p className="field-hint">仅限当前浏览器恢复网络中断的原提交，内容必须与之前完全一致。</p></>}<div><button type="button" className="secondary verify-button" onClick={verifyCards} disabled={!cardKey.trim() || (recoverMode && !recoveryKey.trim())}><ShieldCheck size={16}/>{verifying ? verificationProgress : recoverMode ? '查找原提交' : '验证卡密'}</button>{singleVerification && <p className="verification-success" role="status"><CheckCircle2 size={16}/>{singleVerification.recoveryKey ? '已找到原提交' : '卡密验证通过'} · {singleVerification.planLabel}</p>}</div></div>
    {singleVerification && <div className="form-section"><div className="field-heading"><StepLabel number="02" title="粘贴账号 Session"/><a className="subtle-link" href="https://chatgpt.com/api/auth/session" target="_blank" rel="noopener noreferrer">获取 Session<ArrowUpRight size={14}/></a></div><div className="session-field"><label className="sr-only" htmlFor="session-json">完整 Session JSON</label><textarea id="session-json" className={!show && session ? 'concealed' : ''} rows={5} required autoComplete="off" spellCheck="false" maxLength={100000} placeholder={'在此粘贴完整的 Session JSON\n{ "user": { ... }, "account": { ... }, "accessToken": "..." }'} value={session} onChange={e => setSession(e.target.value)}/><div className="textarea-bottom"><span><FileJson size={13}/>JSON 格式</span><div>{session && <button type="button" onClick={() => setSession('')}>清空</button>}<button type="button" aria-label={show ? '隐藏 Session' : '显示 Session'} onClick={() => setShow(!show)}>{show ? <EyeOff size={15}/> : <Eye size={15}/>}</button></div></div></div>{account ? <p className="account-preview"><CheckCircle2 size={14}/>已识别账号：<strong>{account}</strong></p> : <p className="field-hint session-guide">登录目标 ChatGPT 账号后，打开获取链接<a href="https://chatgpt.com/api/auth/session" target="_blank" rel="noopener noreferrer">https://chatgpt.com/api/auth/session<ArrowUpRight size={12}/></a>，复制完整 JSON 内容。<a href={appPath('/help')}>查看教程<ChevronRight size={12}/></a></p>}</div>}</> : <><div className="form-section batch-section"><div className="field-heading"><StepLabel number="01" title="验证批量卡密"/><button type="button" className="subtle-link" onClick={() => fileRef.current?.click()}><Upload size={14}/>导入卡密文件</button><input ref={fileRef} type="file" accept=".txt" hidden onChange={importFile}/></div><label className="sr-only" htmlFor="batch-input">批量卡密</label><textarea id="batch-input" rows={5} spellCheck="false" autoComplete="off" maxLength={6500} value={batch} onChange={e => { setBatch(e.target.value); setBatchVerifications(null); setBatchSessions(''); setAgreed(false); setError(''); }} placeholder={'每行一张卡密\n第一张卡密\n第二张卡密'}/><p className="field-hint">每行一张卡密，最多 50 张；全部通过验证后可填写对应 Session。</p><button type="button" className="secondary verify-button" onClick={verifyCards} disabled={!batch.trim()}><CheckCheck size={16}/>{verifying ? verificationProgress : '验证全部卡密'}</button>{batchVerifications && <p className="verification-success" role="status"><CheckCircle2 size={16}/>{batchVerifications.length} 张卡密全部通过验证</p>}</div>
    {batchVerifications && <div className="form-section batch-section"><div className="field-heading"><StepLabel number="02" title="按顺序填写账号 Session"/><button type="button" className="subtle-link" onClick={()=>sessionFileRef.current?.click()}><Upload size={14}/>导入 Session 文件</button><input ref={sessionFileRef} type="file" accept=".txt,.json" hidden onChange={importSessions}/></div><p className="field-hint">请按上方卡密顺序，每行粘贴一个完整 Session JSON；也可使用 JSON 数组。</p><label className="sr-only" htmlFor="batch-sessions">批量 Session</label><textarea id="batch-sessions" rows={5} required spellCheck="false" autoComplete="off" maxLength={500000} value={batchSessions} onChange={e=>setBatchSessions(e.target.value)} placeholder={'第一张卡密对应的完整 Session JSON\n第二张卡密对应的完整 Session JSON'}/></div>}</>}
    {(mode === 'single' ? singleVerification : batchVerifications) && <div className="confirmation"><label className="check-label"><input type="checkbox" checked={agreed} onChange={e => setAgreed(e.target.checked)}/><span>我已确认兑换账号正确，并阅读<a href={appPath('/help#terms')} target="_blank" rel="noopener noreferrer">兑换须知</a></span></label><p>提交后请勿重复兑换。订单待核验时，请联系商家确认最终结果。</p></div>}</fieldset>
    <Alert>{error}</Alert>{ready && (!settings.configured || !settings.verificationConfigured) && <Alert type="info">商家尚未完成兑换服务及卡密验证配置，请联系商家。</Alert>}{settings.maintenance && <Alert type="info">兑换服务正在维护，现有订单仍可查询。</Alert>}
    {(mode === 'single' ? singleVerification : batchVerifications) && <button className="primary submit-button" disabled={busy || verifying || disabled || !agreed} type="submit">{busy ? <><Spinner/>正在提交，请稍候</> : <>确认并开始兑换<ArrowRight size={18}/></>}</button>}{busy && mode === 'batch' && <button type="button" className="subtle-link stop-batch" onClick={() => { stop.current = true; }}><Pause size={14}/>在当前订单提交后暂停</button>}
    <div className="form-footnote"><LockKeyhole size={12}/>凭据仅用于处理兑换 · 本站数据库不保存 Session</div></form></section>
    {items.length > 0 && <section className="result-card"><div className="result-heading"><h3>提交回执<span>{items.filter(i=>i.state === 'submitted').length} / {items.length}</span></h3><button className="subtle-link" onClick={() => downloadJson('limen-receipts.json', items)}><Download size={14}/>保存回执</button></div><p className="field-hint">已受理不代表兑换成功，请以下方订单最终状态为准。暂停后的未提交项目可重新粘贴后提交。</p>{items.map((item,i) => <div className="receipt-row" key={i}><span className="receipt-index">{String(item.index).padStart(2,'0')}</span><div><b>{item.email}</b><code>{item.order?.order_no || item.card}</code>{item.message && <p className="row-error">{item.message}</p>}</div><span className={`badge ${item.state === 'submitted' ? 'success' : item.state === 'error' ? 'failed' : 'pending'}`}>{({waiting:'未提交',submitting:'提交中',submitted:'已受理',unknown:'结果未确定',error:'提交未完成'})[item.state]}</span></div>)}{attempt && <p className="field-hint mono">最近提交标识：{attempt}</p>}</section>}
    {orders.length > 0 && <OrderResults orders={orders} setOrders={setOrders} auto/>}
    <div className="bottom-trust"><span><ShieldCheck size={17}/>凭据不落库</span><i/><span><RefreshCw size={16}/>进度可查询</span><i/><span><Layers size={16}/>支持批量兑换</span></div></main><Guide settings={settings}/></div></>;
}
function CopyButton({ value }) { const [copied, setCopied] = useState(false); return <button className="icon-button copy" aria-label="复制订单号" onClick={async () => { try { await navigator.clipboard.writeText(value); setCopied(true); setTimeout(()=>setCopied(false),1600); } catch { /* The full number remains selectable. */ } }}>{copied ? <Check size={14}/> : <Copy size={14}/>}</button>; }
function OrderResults({ orders, setOrders, auto = false }) {
  const [error, setError] = useState(''); const [refreshing, setRefreshing] = useState(false); const [timedOut, setTimedOut] = useState(false); const latest = useRef(orders); latest.current = orders;
  const eligible = orders.filter(o => ['pending','processing','pending_verification'].includes(o.status) && o.subscription_verification_state !== 'needs_attention').map(o=>o.order_no).join(',');
  async function refresh(ids) {
    setRefreshing(true); setError('');
    try { const data = await api('/orders/query', { method: 'POST', body: { order_no: ids || latest.current.map(o=>o.order_no).slice(0,100) } }); setOrders(old => old.map(o=>data.orders.find(n=>n.order_no === o.order_no)||o)); }
    catch (e) { setError(e.message); throw e; } finally { setRefreshing(false); }
  }
  useEffect(() => {
    if (!auto || !eligible) return;
    let cancel = false; let timer; const started = Date.now(); setTimedOut(false);
    async function poll() {
      if (cancel || document.hidden) { if (!cancel) timer = setTimeout(poll, 8000); return; }
      if (Date.now() - started > 180000) { setTimedOut(true); return; }
      try { await refresh(eligible.split(',')); } catch { return; }
      if (!cancel) timer = setTimeout(poll, Date.now()-started < 30000 ? 3000 : 8000);
    }
    timer = setTimeout(poll,3000); return () => { cancel = true; clearTimeout(timer); };
  }, [eligible, auto]);
  return <section className="result-card"><div className="result-heading"><h3>订单进度<span>{orders.length}</span></h3><div className="button-row"><button className="subtle-link" disabled={refreshing} onClick={()=>refresh().catch(()=>{})}>{refreshing ? <Spinner/> : <RefreshCw size={14}/>}刷新</button><button className="subtle-link" onClick={() => downloadJson('limen-orders.json', orders)}><Download size={14}/>导出</button></div></div><Alert>{error}</Alert>{timedOut && <Alert type="info">自动查询已暂停，订单仍可能处理中。请稍后手动刷新，勿重复提交。</Alert>}{orders.map(o=><article className="order-item" key={o.order_no}><div className="order-top"><span className={`badge ${(STATUS[o.status]||['未知状态','pending'])[1]}`}>{o.status === 'success' ? <CheckCircle2 size={13}/> : <Clock3 size={13}/>} {(STATUS[o.status]||['未知状态'])[0]}</span><span className="muted">{o.plan_type?.toUpperCase() || (o.order_type === 'card_key' ? '卡密兑换' : '银行卡直充')}</span></div><h4>{o.email || '账号信息待同步'}</h4><div className="order-no"><code>{o.order_no}</code><CopyButton value={o.order_no}/></div>{o.status === 'pending_verification' && <Alert type="warning"><strong>请勿重复充值</strong><br/>{o.subscription_verification_reason || '订阅结果正在核验，请等待确认。'}<br/>{o.payment_confirmed ? '上游已确认支付，订阅状态尚需核实。' : '支付结果尚未确认，不能据此判断是否扣款。'}{o.subscription_verification_state === 'needs_attention' && <><br/>自动查询已停止，请联系商家人工核实。</>}</Alert>}{o.failure_reason && o.status === 'failed' && <Alert>{o.failure_reason}</Alert>}<div className="order-meta"><span>{o.created_at || '已受理，等待上游更新'}</span>{o.payment_amount && <span>{o.payment_amount} {o.payment_currency}</span>}{o.status === 'success' && <span>{o.is_subscription_cancelled ? '自动续费已取消' : '自动续费状态待同步'}</span>}</div></article>)}</section>;
}
function SubscriptionPage({ ready }) {
  const [raw, setRaw] = useState(''); const [result, setResult] = useState(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [show, setShow] = useState(false); const lock = useRef(false); const controller = useRef(null);
  useEffect(()=>()=>controller.current?.abort(),[]);
  function clear() { controller.current?.abort(); controller.current=null; setRaw(''); setResult(null); setError(''); setBusy(false); lock.current=false; }
  async function query(e) {
    e.preventDefault(); if (lock.current || !ready || !raw.trim()) return;
    lock.current=true; setBusy(true); setError(''); setResult(null);
    const request = new AbortController(); controller.current=request;
    try { const d=await api('/subscription/query',{method:'POST',body:{session:raw.trim()},signal:request.signal}); if(controller.current!==request)return; setResult(d.subscription); setRaw(''); }
    catch(e) { if(controller.current===request)setError(e.code==='RESULT_UNKNOWN'?'连接中断，暂时无法查询订阅，请稍后重试。':e.message); }
    finally { if(controller.current===request){setBusy(false);lock.current=false;controller.current=null;} }
  }
  const date = value => value ? new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Hong_Kong',hour12:false}) : '上游未提供';
  const plans = {free:'ChatGPT Free',chatgptfreeplan:'ChatGPT Free',plus:'ChatGPT Plus',chatgptplusplan:'ChatGPT Plus',go:'ChatGPT Go',pro:'ChatGPT Pro',team:'ChatGPT Team',business:'ChatGPT Business'};
  return <section className="subscription-panel"><div className="provider-tabs"><span className="selected">ChatGPT</span></div>{!result&&<form className="subscription-form" onSubmit={query}><div className="field-heading"><label className="input-label" htmlFor="subscription-session">输入 Session</label><button type="button" className="subtle-link" onClick={()=>setShow(!show)}>{show?<EyeOff size={15}/>:<Eye size={15}/>} {show?'隐藏':'显示'}</button></div><textarea id="subscription-session" rows={6} className={!show&&raw?'concealed':''} value={raw} disabled={busy} onChange={e=>{setRaw(e.target.value);setResult(null);setError('');}} autoComplete="off" spellCheck="false" maxLength={100000} placeholder="粘贴 chatgpt.com/api/auth/session 的完整 JSON，或直接粘贴 accessToken"/><p className="field-hint">通过充值服务商实时查询订阅，本站不保存 Session。<a href="https://chatgpt.com/api/auth/session" target="_blank" rel="noopener noreferrer">获取 Session（https://chatgpt.com/api/auth/session）<ArrowUpRight size={13}/></a></p><Alert>{error}</Alert><div className="subscription-actions"><button type="button" className="secondary" onClick={clear}>清空</button><button className="primary" disabled={busy||!ready||!raw.trim()}>{busy?<><Spinner/>正在查询</>:<><Search size={17}/>查询订阅</>}</button></div></form>}{result&&<section className="subscription-result" aria-live="polite"><div className="subscription-result-title"><div><span className="section-kicker">订阅信息</span><h2>{plans[result.plan.toLowerCase()]||result.plan}</h2></div><span className={`badge ${result.active?'success':'neutral'}`}>{result.active?<CheckCircle2 size={14}/>:<CircleHelp size={14}/>} {result.active?'订阅有效':'无有效订阅'}</span></div><p className="subscription-summary">{!result.active?'当前账号没有有效订阅。':result.willRenew===true?'当前订阅有效，自动续费已开启。':result.willRenew===false?'当前订阅有效，自动续费已关闭。':'当前订阅有效，自动续费状态暂未提供。'}</p><dl className="subscription-details">{[['账号邮箱',result.email||'上游未提供'],['到期时间',date(result.expiresAt)],['订阅开始',date(result.startedAt)],['自动续费',result.willRenew===null?'上游未提供':result.willRenew?'已开启':'已关闭'],['计费周期',({month:'月付',monthly:'月付',year:'年付',yearly:'年付',annual:'年付'})[result.billingPeriod]||result.billingPeriod||'上游未提供'],['支付渠道',({web:'网页支付',stripe:'网页支付',apple:'App Store',ios:'App Store',google:'Google Play'})[result.paymentChannel]||result.paymentChannel||'上游未提供']].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl><p className="field-hint">查询时间：{date(result.checkedAt)}（北京时间）</p><button type="button" className="primary query-another" onClick={clear}>查询其他账号</button></section>}</section>;
}
function OrdersPage() {
  const [input, setInput] = useState(''); const [orders, setOrders] = useState([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [loading, setLoading] = useState(true);
  useEffect(()=>{ api('/orders').then(d=>setOrders(d.orders)).catch(e=>setError(e.message)).finally(()=>setLoading(false)); },[]);
  async function query(e) { e.preventDefault(); setError(''); const ids = [...new Set(input.split(/[\s,;，；]+/).filter(Boolean))]; if (!ids.length || ids.length > 100 || ids.some(id=>!/^[a-f\d]{8}-(?:[a-f\d]{4}-){3}[a-f\d]{12}$/i.test(id))) {setError('请输入完整订单 UUID，每次最多查询 100 条。');return;} setBusy(true); try { const d = await api('/orders/query',{method:'POST',body:{order_no:ids.length===1?ids[0]:ids}});setOrders(d.orders);if(!d.orders.length)setError('未找到匹配订单。'); } catch(e){setError(e.message);} finally{setBusy(false);} }
  return <><Hero compact tag="EVERY STEP, IN SIGHT." title={<>兑换进度，<em>随时掌握。</em></>} subtitle="输入完整订单号，查询每一笔兑换的处理结果。"/><div className="workspace"><main className="main-column"><section className="redeem-card query-card"><div className="card-heading"><div><span className="section-kicker">TRACK YOUR ORDER</span><h2>订单查询</h2></div><Search size={25} strokeWidth={1.5}/></div><form onSubmit={query}><label htmlFor="order-search" className="input-label">订单号 <span>支持单笔 / 批量</span></label><textarea id="order-search" rows={3} maxLength={4000} value={input} onChange={e=>setInput(e.target.value)} placeholder="粘贴创建成功后获得的完整订单号，多条使用换行分隔"/><p className="field-hint">每次最多查询 100 条。为保护隐私，前台仅能查询当前浏览器提交的订单。</p><Alert>{error}</Alert><button className="primary" disabled={busy || !input.trim()}>{busy?<Spinner/>:<Search size={17}/>}查询订单</button></form></section>{loading?<div className="empty-state"><Spinner/>正在加载本机订单…</div>:orders.length?<OrderResults orders={orders} setOrders={setOrders} auto/>:<div className="empty-state"><div className="empty-icon"><Search size={27} strokeWidth={1.4}/></div><h3>每一次兑换，都有迹可循</h3><p>当前浏览器的最近 100 笔订单会显示在这里。</p><a href={appPath('/')} className="text-link">前往兑换中心<ArrowRight size={15}/></a></div>}</main><aside className="sidebar"><div className="guide-card"><span className="eyebrow">A NOTE ON STATUS</span><h3>读懂每一步状态。</h3><div className="status-guide">{[['pending','排队 / 处理中','已受理，请等待最终结果。'],['attention','待核验','请勿重复兑换；需人工核验时联系商家。'],['success','兑换成功','订阅已成功，可登录账号查看。'],['failed','兑换失败','查看原因，联系商家协助处理。']].map(([c,t,d])=><div key={c}><span className={`status-dot ${c}`}/><div><b>{t}</b><p>{d}</p></div></div>)}</div></div><div className="help-note"><ShieldCheck size={20}/><p>请保管好订单回执。跨设备或清除浏览器 Cookie 后，请联系商家协助查询。</p></div></aside></div></>;
}
const FAQ = [
  ['如何查询订阅状态？', '打开订阅查询，粘贴完整 Session JSON 或 accessToken，即可通过充值服务商实时获取套餐、有效状态、到期时间和自动续费状态。本站不保存查询凭据；查询失败不能当作没有订阅，缺失字段会显示上游未提供。'],
  ['如何获取完整的 Session？', <>先在浏览器登录需要兑换的 ChatGPT 账号，再打开 <a href="https://chatgpt.com/api/auth/session" target="_blank" rel="noopener noreferrer">chatgpt.com/api/auth/session <ExternalLink size={12}/></a>，复制页面返回的完整 JSON。需包含 user.email、account.id 和有效的 accessToken；无需向本站提供账号密码。</>],
  ['批量兑换需要什么格式？', <>先输入或导入卡密，每行一张。全部验证通过后，按卡密的相同顺序输入 Session，每行一个完整 JSON，也可导入 .txt 文件或 Session JSON 数组。每批最多 50 组，同一卡密及账号不能重复。</>],
  ['点击提交后，是否就代表兑换成功？', '提交成功仅代表订单已受理。请保存完整订单号，并在订单查询页等待“兑换成功”的最终状态。不要因为等待时间较长重复提交。'],
  ['订单显示“待核验”应该怎么做？', '待核验既不是成功，也不是失败。请查看核验说明；如果标记需要人工核实，自动查询会停止，请联系商家。支付未确认不能被视为未扣款。此时禁止重复创建充值订单。'],
  ['网络中断或超时了，可以重新提交吗？', '网络错误不代表订单未创建。已有订单号时先查询原订单；未取得订单号时保留原始内容，在同一浏览器标签页使用完全相同内容重试，系统会复用原提交标识。请保存回执中的提交标识；若已关闭标签页或修改内容，先联系商家核实。'],
  ['可以取消订单、更换卡密或查询卡密余额吗？', '当前商户 API 没有提供取消、换码、余额及套餐列表接口。本站只展示文档支持的能力，其他需求请联系商家。'],
];
function HelpPage({ settings }) {
  const getSection = () => ['terms', 'privacy'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'faq';
  const [section, setSection] = useState(getSection);
  useEffect(() => { const update = () => setSection(getSection()); window.addEventListener('hashchange', update); return () => window.removeEventListener('hashchange', update); }, []);
  function selectSection(next) { setSection(next); history.replaceState(null, '', next === 'faq' ? location.pathname : `#${next}`); }
  return <><Hero compact tag="A LITTLE HELP GOES A LONG WAY." title={<>使用指南，<em>一步就懂。</em></>} subtitle="从准备信息到查询结果，您可能需要的答案都在这里。"/><div className="help-layout">
    <nav className="help-tabs" aria-label="帮助分类">{[['faq','常见问题'],['terms','兑换须知'],['privacy','隐私与安全']].map(([id,label])=><button key={id} type="button" className={section===id?'selected':''} aria-current={section===id?'page':undefined} onClick={()=>selectSection(id)}>{label}</button>)}</nav>
    {section==='faq'&&<section className="redeem-card faq"><div className="card-heading"><div><span className="section-kicker">GOOD TO KNOW</span><h2>常见问题</h2></div><CircleHelp size={25} strokeWidth={1.5}/></div>{FAQ.map(([q,a],i)=><details key={q} open={i===0}><summary>{q}<ChevronDown size={17}/></summary><div>{a}</div></details>)}</section>}
    {section==='terms'&&<section id="terms" className="info-section"><span className="section-kicker">BEFORE YOU REDEEM</span><h2>兑换须知</h2><p>请确认卡密来源、兑换目标及账号邮箱正确。兑换成功以订单查询最终结果为准；订单处于处理中或待核验时，不得重复充值。银行卡直充仅在商户后台开放，可能产生实际支付和商户积分消耗，管理员应确认套餐及地区配置后再提交。</p><p>本站不提供账号出售或凭据共享服务。具体商品、退款及售后约定以向您提供卡密的商家说明为准。{settings.supportText}</p></section>}
    {section==='privacy'&&<section id="privacy" className="info-section privacy-info"><ShieldCheck size={28}/><div><span className="section-kicker">YOUR PRIVACY MATTERS</span><h2>隐私与安全</h2><p>Session 会通过本站后端转交给充值服务商（admin-lm.zdhxylc.shop）完成兑换或订阅查询。订阅查询只转发 accessToken 和必要的账号身份字段，不转发 sessionToken；查询结果只在当前页面展示。本站不将 Session、银行卡完整卡号或 CVV 写入数据库、浏览器持久存储和业务日志；内存中的输入会在成功提交后清除。服务商如何保存处理凭据，请向商家核实。</p><p>本站会保存加密的必要订单信息（包括订单号、邮箱、状态）、去重摘要及最小化操作审计，用于查询和处理异常。默认保留至运营方按实际需要清理；浏览器身份 Cookie 有效期 30 天，后台登录权限有效期 8 小时。只有当前浏览器及管理员可以访问相应订单。提交标识摘要保存在当前标签页会话存储中，用于安全重试。</p><p>生产部署须启用 HTTPS。请勿在公共设备留存凭据，完成后关闭相关页面；如怀疑 Session 泄露，请及时退出账号并撤销相关会话。</p></div></section>}
  </div></>;
}

function Admin({ session, onSession }) {
  const [tab, setTab] = useState('overview'); const [password,setPassword] = useState(''); const [busy,setBusy] = useState(false); const [error,setError] = useState(''); const [success,setSuccess] = useState(''); const [overview,setOverview] = useState(null); const [auditPage,setAuditPage] = useState(0); const [settings,setSettings] = useState(null); const [key,setKey] = useState(''); const [clearKey,setClearKey] = useState(false);
  async function load() { setError(''); try { const [o,s] = await Promise.all([api('/admin/overview'),api('/admin/settings')]);setOverview(o);setSettings(s); }catch(e){setError(e.message); if(e.status===401)onSession(s=>({...s,admin:false}));} }
  useEffect(()=>{if(session.admin)load();},[session.admin]);
  async function login(e){e.preventDefault();setBusy(true);setError('');try{await api('/admin/login',{method:'POST',body:{password}});setPassword('');onSession(s=>({...s,admin:true}));}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function save(e){e.preventDefault();setBusy(true);setError('');setSuccess('');try{const {siteName,announcement,maintenance,allowBatch,supportText,verificationSite}=settings;const data=await api('/admin/settings',{method:'PUT',body:{siteName,announcement,maintenance,allowBatch,supportText,verificationSite,...(key?{apiKey:key}:{}),...(clearKey?{clearApiKey:true}:{})}});setSettings(s=>({...s,...data}));onSession(s=>({...s,settings:data}));setKey('');setClearKey(false);setSuccess('配置已安全保存，将对新请求生效。');}catch(e){setError(e.message);}finally{setBusy(false);}}
  if(!session.admin)return <div className="login-layout"><div className="login-art"><span className="eyebrow">THE OTHER SIDE OF SIMPLE.</span><h1>有序管理，<br/><em>从容运营。</em></h1><p>所有兑换，一个工作台。<br/>安全地连接您的商户服务。</p><div className="login-art-icon"><Leaf size={80} strokeWidth={0.8}/></div></div><section className="login-card"><span className="login-lock"><LockKeyhole size={23}/></span><span className="section-kicker">MERCHANT WORKSPACE</span><h2>欢迎回到商户后台</h2><p>请输入初始化时生成的管理员密码。</p><form onSubmit={login}><label className="input-label" htmlFor="admin-password">管理员密码</label><input id="admin-password" type="password" autoComplete="current-password" required maxLength={256} value={password} onChange={e=>setPassword(e.target.value)} placeholder="请输入管理员密码"/><Alert>{error}</Alert><button className="primary" disabled={busy||!password}>{busy?<Spinner/>:<>安全登录<ArrowRight size={17}/></>}</button></form><a className="subtle-link" href={appPath('/')}><ArrowLeft size={14}/>返回兑换中心</a></section></div>;
  const tabs=[['overview',LayoutDashboard,'工作台'],['orders',Layers,'订单管理'],['direct',CreditCard,'银行卡直充'],['lookup',Search,'卡号邮箱补查'],['settings',Settings2,'服务配置']];
  return <div className="admin-layout"><aside className="admin-sidebar"><span className="section-kicker">MERCHANT WORKSPACE</span><h2>商户工作台</h2><nav>{tabs.map(([id,Icon,title])=><button className={tab===id?'active':''} key={id} onClick={()=>{setTab(id);setError('');setSuccess('');}}><Icon size={18}/>{title}<ChevronRight size={14}/></button>)}</nav><div className="admin-security"><ShieldCheck size={20}/><p>密钥由服务器加密保存，前端仅显示配置状态。</p></div><button className="subtle-link" onClick={async()=>{try{await api('/admin/logout',{method:'POST',body:{}});onSession(s=>({...s,admin:false}));}catch(e){setError(e.message);}}}><LogOut size={16}/>退出登录</button></aside><main className="admin-main"><div className="admin-heading"><div><span className="eyebrow">LESS FRICTION. MORE CONTROL.</span><h1>{tabs.find(t=>t[0]===tab)[2]}</h1></div><button className="secondary small" onClick={load}><RefreshCw size={15}/>刷新数据</button></div><Alert>{error}</Alert>{success&&<Alert type="info">{success}</Alert>}
  {tab==='overview'&&<><div className="stats-grid">{[['全部订单',overview?.counts.reduce((a,c)=>a+c.total,0)||0],['兑换成功',overview?.counts.find(c=>c.status==='success')?.total||0],['进行 / 待核验',overview?.counts.filter(c=>['pending','processing','pending_verification'].includes(c.status)).reduce((a,c)=>a+c.total,0)||0],['待确认提交',overview?.unresolved||0]].map(([t,n])=><div className="stat-card" key={t}><span>{t}</span><b>{n}</b><span className="stat-caption">本站已记录数据</span></div>)}</div>{!!overview?.unresolved&&<Alert type="warning">有提交因网络异常尚未确定结果。请让提交者保留原始内容与提交标识；银行卡订单可使用卡号邮箱补查，卡密订单请到上游商户工作台核实。不要直接释放占用后重复充值。</Alert>}<div className="admin-welcome"><div><span className="eyebrow">READY WHEN YOU ARE.</span><h2>每笔兑换，都有清晰的去向。</h2><p>{settings?.configured?'商户 API 已配置，您可以管理本站订单或提交直充。':'先配置您的商户 API Key，再开始提供兑换服务。'}</p><button className="primary small" onClick={()=>setTab(settings?.configured?'orders':'settings')}>{settings?.configured?'查看订单':'前往配置'}<ArrowRight size={16}/></button></div><ShieldCheck size={90} strokeWidth={0.8}/></div><section className="result-card"><div className="audit-heading"><h3>最近操作</h3>{overview?.audit.length>3&&<div className="audit-pagination"><button type="button" disabled={auditPage===0} onClick={()=>setAuditPage(page=>page-1)}>上一页</button><span>{auditPage+1} / {Math.ceil(overview.audit.length/3)}</span><button type="button" disabled={(auditPage+1)*3>=overview.audit.length} onClick={()=>setAuditPage(page=>page+1)}>下一页</button></div>}</div><div className="audit-list">{overview?.audit.length?overview.audit.slice(auditPage*3,auditPage*3+3).map(a=><div key={a.id}><span>{({login_success:'管理员登录',login_failed:'登录验证失败',logout:'管理员退出',settings_updated:'更新服务配置',settings_and_key_updated:'更新密钥 / 服务配置',order_created:'创建订单',order_lookup:'执行卡号邮箱补查'})[a.action]||a.action}</span><time>{new Date(a.created).toLocaleString('zh-CN',{timeZone:'Asia/Hong_Kong',hour12:false})}</time></div>):<p className="muted">暂无操作记录</p>}</div></section></>}
  {tab==='settings'&&settings&&<form className="redeem-card settings-form" onSubmit={save}>
    <div className="settings-columns">
      <section className="settings-column"><div className="settings-title"><KeyRound size={20}/><div><h3>API 连接</h3><p>密钥保存后无法读回；留空表示保留现有配置。</p></div></div>
        <label className="input-label" htmlFor="api-base">API 地址</label><input id="api-base" readOnly value={settings.apiBase}/><p className="field-hint">固定为文档提供的 HTTPS 地址，禁止任意代理目的地址。</p>
        <label className="input-label" htmlFor="api-key">API Key <span className={settings.configured?'configured':''}>{settings.configured?'已配置':'未配置'}</span></label><input id="api-key" type="password" autoComplete="new-password" value={key} onChange={e=>{setKey(e.target.value);setClearKey(false);}} maxLength={512} placeholder={settings.configured?'留空保留原密钥，填写则替换':'输入商户个人中心生成的 API Key'}/>
        <label className="input-label" htmlFor="verification-site">上游兑换站标识 <span>{settings.verificationConfigured?'已配置':'未配置'}</span></label><input id="verification-site" autoComplete="off" value={settings.verificationSite || ''} maxLength={32} pattern="[a-z0-9][a-z0-9-]{2,31}" onChange={e=>setSettings({...settings,verificationSite:e.target.value.toLowerCase().trim()})} placeholder="例如 m-702"/><p className="field-hint">填写上游商户兑换站地址 /s/ 后面的标识，必须与 API Key 属于同一商户。</p>
        {settings.configured&&<label className="check-label danger-check"><input type="checkbox" checked={clearKey} onChange={e=>{setClearKey(e.target.checked);if(e.target.checked)setKey('');}}/>删除当前密钥并停止新兑换</label>}
      </section>
      <section className="settings-column"><div className="settings-title"><Settings2 size={20}/><div><h3>网站设置</h3><p>修改后会对前台新访问生效。</p></div></div>
        <label className="input-label" htmlFor="site-name">网站名称</label><input id="site-name" value={settings.siteName} maxLength={30} required onChange={e=>setSettings({...settings,siteName:e.target.value})}/>
        <label className="input-label" htmlFor="announcement">服务公告</label><textarea id="announcement" rows={3} maxLength={300} value={settings.announcement} onChange={e=>setSettings({...settings,announcement:e.target.value})}/>
        <label className="input-label" htmlFor="support">售后联系说明</label><input id="support" maxLength={150} value={settings.supportText} onChange={e=>setSettings({...settings,supportText:e.target.value})}/>
      </section>
    </div>
    <div className="settings-toggles">{[['maintenance','暂停新订单','维护期间保留订单查询能力。'],['allowBatch','开放批量兑换','允许前台一次导入最多 50 组兑换信息。']].map(([k,t,d])=><label key={k} className="toggle-row"><div><b>{t}</b><p>{d}</p></div><input type="checkbox" role="switch" checked={settings[k]} onChange={e=>setSettings({...settings,[k]:e.target.checked})}/></label>)}</div>
    <button className="primary" disabled={busy}>{busy?<Spinner/>:<><LockKeyhole size={16}/>安全保存配置</>}</button></form>}
  {tab==='orders'&&<AdminOrders initialOrders={overview?.recentOrders||[]}/>}{tab==='direct'&&<DirectForm/>}{tab==='lookup'&&<LookupForm/>}</main></div>;
}
function AdminOrders({initialOrders}){const[orders,setOrders]=useState(initialOrders);const[input,setInput]=useState('');const[error,setError]=useState('');const[busy,setBusy]=useState(false);useEffect(()=>setOrders(initialOrders),[initialOrders]);async function query(e){e.preventDefault();setBusy(true);setError('');try{const ids=[...new Set(input.split(/[\s,;，；]+/).filter(Boolean))];if(!ids.length||ids.length>100)throw new Error('每次查询 1–100 个订单号');const d=await api('/orders/query',{method:'POST',body:{order_no:ids}});setOrders(d.orders);if(!d.orders.length)setError('未找到匹配订单');}catch(e){setError(e.message);}finally{setBusy(false);}}return <><form className="redeem-card admin-query" onSubmit={query}><h3>按订单号查询</h3><p>可查询当前 API Key 所属商户的历史 API 订单。下方默认显示本站最近 100 笔记录。</p><textarea aria-label="管理员批量订单号" rows={3} maxLength={4000} value={input} onChange={e=>setInput(e.target.value)} placeholder="每行一个完整订单 UUID，最多 100 条"/><Alert>{error}</Alert><button className="primary small" disabled={busy||!input.trim()}>{busy?<Spinner/>:<Search size={15}/>}查询订单</button></form>{orders.length?<OrderResults orders={orders} setOrders={setOrders}/>:<div className="empty-state"><Layers size={28}/><h3>暂无订单记录</h3></div>}</>}
function DirectForm(){const[raw,setRaw]=useState('');const[batch,setBatch]=useState(false);const[error,setError]=useState('');const[busy,setBusy]=useState(false);const[agreed,setAgreed]=useState(false);const[orders,setOrders]=useState([]);const[receipts,setReceipts]=useState([]);const[form,setForm]=useState({cardNumber:'',expMonth:'',expYear:'',cvv:'',country:'PH',planType:'plus'});const lock=useRef(false);
async function submit(e){e.preventDefault();if(lock.current)return;setError('');let payloads;try{if(!agreed)throw new Error('请先确认直充支付及积分消耗。');payloads=batch?JSON.parse(raw):[{orderType:'direct',...form,expMonth:Number(form.expMonth),expYear:Number(form.expYear),token:parseSession(raw)}];if(!Array.isArray(payloads)||!payloads.length||payloads.length>50)throw new Error('直充批量内容应为 1–50 项请求对象的 JSON 数组。');payloads=payloads.map(p=>({...p,orderType:'direct',token:parseSession(p.token)}));}catch(e){setError(e.message);return;}lock.current=true;setBusy(true);const result=[];let ok=true;for(let i=0;i<payloads.length;i++){try{const key=await submissionKey(payloads[i]);const d=await api('/orders',{method:'POST',body:payloads[i],headers:{'Idempotency-Key':key,...(batch?{'X-Batch-Mode':'1'}:{})}});setOrders(old=>[d.order,...old.filter(o=>o.order_no!==d.order.order_no)]);result.push({index:i+1,attempt:key,order_no:d.order.order_no});}catch(e){ok=false;setError(`第 ${i+1} 项：${e.message}；后续项目未提交。`);break;}if(i<payloads.length-1)await new Promise(r=>setTimeout(r,850));}setReceipts(result);if(ok){setRaw('');setForm(f=>({...f,cardNumber:'',cvv:'',expMonth:'',expYear:''}));setAgreed(false);}setBusy(false);lock.current=false;}
return <><form className="redeem-card direct-form" onSubmit={submit}><h3>创建银行卡直充订单</h3><p className="muted">仅限管理员，需使用合法授权的支付信息。支持 go / plus / pro5 / pro20 / pro50。</p><Alert type="warning">提交可能产生真实银行卡扣款及商户积分消耗。套餐和地区是否可用，由上游平台配置决定。不要提交仍处于处理中或待核验的账号。</Alert><fieldset disabled={busy}><label className="check-label"><input type="checkbox" checked={batch} onChange={e=>{setBatch(e.target.checked);setRaw('');setAgreed(false);}}/>批量直充（JSON 数组，最多 50 项）</label>{!batch&&<div className="direct-grid">{[['cardNumber','银行卡号','text',19],['expMonth','到期月','number',2],['expYear','到期年','number',4],['cvv','CVV','password',4],['country','地区代码','text',2]].map(([k,label,type,max])=><label className={k==='cardNumber'?'full':''} key={k}>{label}<input aria-label={label} type={type} value={form[k]} maxLength={max} autoComplete="off" required onChange={e=>setForm({...form,[k]:e.target.value})}/></label>)}<label>套餐<select value={form.planType} onChange={e=>setForm({...form,planType:e.target.value})}>{['go','plus','pro5','pro20','pro50'].map(p=><option key={p} value={p}>{p.toUpperCase()}</option>)}</select></label></div>}<label className="input-label" htmlFor="direct-token">{batch?'完整直充请求数组':'完整账号 Session'}</label><textarea id="direct-token" rows={8} value={raw} maxLength={500000} autoComplete="off" spellCheck="false" required onChange={e=>setRaw(e.target.value)} placeholder={batch?'[{"orderType":"direct","cardNumber":"…","expMonth":12,"expYear":2030,"cvv":"…","planType":"plus","country":"PH","token":{…}}]':'粘贴完整 Session JSON'}/><label className="check-label"><input type="checkbox" checked={agreed} onChange={e=>setAgreed(e.target.checked)}/>我已核对账号、套餐和支付信息，确认提交可能发生扣款与积分消耗</label></fieldset><Alert>{error}</Alert><button className="primary" disabled={busy||!agreed}>{busy?<Spinner/>:<>确认创建直充订单<ArrowRight size={16}/></>}</button></form>{receipts.length>0&&<button className="secondary download-receipt" onClick={()=>downloadJson('direct-receipts.json',receipts)}><Download size={15}/>下载本次直充回执（{receipts.length} 条）</button>}{orders.length>0&&<OrderResults orders={orders} setOrders={setOrders} auto/>}</>}
function LookupForm(){const[cardNumber,setCard]=useState('');const[email,setEmail]=useState('');const[orders,setOrders]=useState([]);const[error,setError]=useState('');const[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);setError('');try{const d=await api('/admin/lookup',{method:'POST',body:{cardNumber,email}});setOrders(d.orders);setCard('');if(!d.orders.length)setError('未找到匹配订单');}catch(e){setError(e.message);}finally{setBusy(false);}}return <><form className="redeem-card lookup-form" onSubmit={submit}><h3>按完整卡号与邮箱补查</h3><p className="muted">仅查询当前商户的 API 订单，每条业务链返回最新重试记录。卡号不会保存。</p><label className="input-label" htmlFor="lookup-card">完整银行卡号</label><input id="lookup-card" type="password" autoComplete="off" pattern="[0-9]{12,19}" required value={cardNumber} onChange={e=>setCard(e.target.value)} maxLength={19}/><label className="input-label" htmlFor="lookup-email">订单账号邮箱</label><input id="lookup-email" type="email" autoComplete="off" required maxLength={255} value={email} onChange={e=>setEmail(e.target.value)}/><Alert>{error}</Alert><button className="primary" disabled={busy}>{busy?<Spinner/>:<Search size={16}/>}查询最新业务记录</button></form>{orders.length>0&&<OrderResults orders={orders} setOrders={setOrders}/>}</>}
function App() {
  const [session,setSession]=useState({admin:false,settings:DEFAULTS}); const [ready,setReady]=useState(false); const [error,setError]=useState('');
  const pathname=pagePath(location.pathname);
  const path=(pathname==='/limdh-admin'||pathname.startsWith('/limdh-admin/'))?'admin':pathname.startsWith('/orders')?'orders':pathname.startsWith('/subscription')?'subscription':pathname.startsWith('/help')?'help':'recharge';
  useEffect(()=>{api('/session').then(s=>{setSession(s);setReady(true);}).catch(e=>setError(e.message));},[]);
  useEffect(()=>{document.title='GPT会员|CDK兑换';},[]);
  return <div className={path==='admin'?'admin-app':'portal-shell'}>{path==='admin'?<Header path={path} name={session.settings.siteName}/>:<PortalHeader path={path} settings={session.settings} ready={ready}/>}<div className={`page-container ${path==='admin'?'admin-container':''}`}>{error&&<Alert>{error} 请刷新页面重试。</Alert>}{path==='admin'?ready?<Admin session={session} onSession={setSession}/>:<div className="empty-state"><Spinner/>正在加载安全会话…</div>:path==='orders'?ready?<OrdersPage/>:<div className="empty-state"><Spinner/>正在加载…</div>:path==='subscription'?<SubscriptionPage ready={ready}/>:path==='help'?<HelpPage settings={session.settings}/>:<Recharge settings={session.settings} ready={ready}/>}</div>{path==='admin'?<Footer/>:<footer className="portal-footer"><a href={appPath('/help#privacy')}><ShieldCheck size={14}/>隐私与安全</a><span>{session.settings.siteName}</span></footer>}</div>;
}
createRoot(document.getElementById('root')).render(<App/>);
